<div class="page-head"><div><span class="eyebrow">ACADÉMICO · MATRÍCULA</span><h1><?=htmlspecialchars($student['nombre'])?></h1><p><?=htmlspecialchars($student['numero_identificacion'])?> · <?=htmlspecialchars($student['codigo_estudiante'])?></p></div><a class="btn secondary" href="<?=$u?>/admin/academico/historial?id=<?=$student['id']?>">Historial académico</a></div>
<section class="card"><div class="section-head"><div><span class="eyebrow">TRAYECTORIAS</span><h2>Selecciona la carrera a matricular</h2></div></div><div class="table-scroll"><table><thead><tr><th>Carrera / malla</th><th>Sede / modalidad</th><th>Estado</th><th>Nivel</th><th>Bloqueos</th><th></th></tr></thead><tbody><?php foreach($trajectories as $x):?><tr><td><strong><?=htmlspecialchars($x['carrera'])?></strong><br><small><?=htmlspecialchars($x['malla_codigo'].' · '.$x['malla'])?></small></td><td><?=htmlspecialchars($x['sede']?:'—')?> · <?=htmlspecialchars($x['modalidad']?:'—')?></td><td><span class="badge <?=$x['permite_matricula']&&$x['activo']?'success':'muted'?>"><?=htmlspecialchars($x['estado'])?></span></td><td><?=htmlspecialchars($x['nivel']?:'—')?></td><td><?=(int)$x['bloqueos']?><br><small><?=(int)$x['bloqueos']?'Bloqueo activo':'Sin bloqueos'?></small></td><td><?php if($x['permite_matricula']&&$x['activo']&&!(int)$x['bloqueos']):?><a href="<?=$u?>/admin/academico/matriculas/propuesta?trayectoria_id=<?=$x['id']?>">Generar propuesta</a><?php else:?><span class="muted-link">No habilitada</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$trajectories):?><tr><td colspan="6">El estudiante no tiene trayectorias académicas.</td></tr><?php endif;?></tbody></table></div></section>
